// ===== سحب معاملات باي موب لآخر N يوم =====
// اكتشافات التشخيص: الصفحة 10 معاملات بس، وباي موب بيرمي 500 على
// الصفحات العميقة. فبنجرّب page_size كبير الأول، وبنتخطى الصفحة اللي
// بترجّع 500 بدل ما نوقف، والحفظ ON CONFLICT (id) فالتكرار مستحيل.
const auth  = $('توكن باي موب').first().json;
const token = auth && (auth.token || auth.access_token);

const DAYS      = 14;
const PAGE_SIZE = 200;         // بنجرّبه؛ لو باي موب مابيحترمهوش بيرجع 10
const MAX_PAGES = 120;
const BUDGET_MS = 4 * 60000;   // سقف وقت النود
const MAX_FAILS = 6;           // كام صفحة فاشلة (500) نتخطاها قبل ما نستسلم
const cutoff    = Date.now() - DAYS * 24 * 60 * 60 * 1000;
const started   = Date.now();

const terminalMapping = {
  "1139384": { branch: "المعمورة",    machine: "paymob1" },
  "1157596": { branch: "المعمورة",    machine: "paymob7" },
  "1157119": { branch: "سان ستيفانو", machine: "paymob2" },
  "1029607": { branch: "سان ستيفانو", machine: "paymob3" },
  "1157121": { branch: "سان ستيفانو", machine: "paymob6" },
  "1002249": { branch: "سيدي بشر",    machine: "paymob4" },
  "1029609": { branch: "سيدي بشر",    machine: "paymob5" }
};
const allowed = Object.keys(terminalMapping);

const dbg = { صفحات:0, حجم_الصفحة:null, خام:0, اتحفظ:0, صفحات_فشلت:0,
              السبب:'', آخر_خطأ:'', أقدم_يوم:null, ثواني:0 };
if (!token) return [{ json: { _debug: Object.assign(dbg, { السبب:'التوكن مش واصل' }) } }];

const BASE = 'https://accept.paymob.com/api/acceptance/transactions';
const pageUrl = (p) => BASE + '?page_size=' + PAGE_SIZE + '&page=' + p;

const pull = (url) => this.helpers.httpRequest({
  method: 'GET', url, headers: { Authorization: token }, json: true, timeout: 60000
});
// 3 محاولات للصفحة الواحدة (الـ500 بتاع باي موب أغلبه لحظي)
async function pullRetry(url) {
  let err = null;
  for (let a = 1; a <= 3; a++) {
    try { return { ok: true, data: await pull(url) }; }
    catch (e) { err = e; if (a < 3) await new Promise(r => setTimeout(r, a * 2000)); }
  }
  return { ok: false, err };
}

const out = [], seen = new Set();
let page = 0, fails = 0, stop = false, oldestSeen = null;

while (!stop && page < MAX_PAGES) {
  if (Date.now() - started > BUDGET_MS) { dbg.السبب = 'خلص وقت النود'; break; }
  page++;

  const r = await pullRetry(pageUrl(page));
  if (!r.ok) {
    fails++; dbg.صفحات_فشلت = fails;
    dbg.آخر_خطأ = 'صفحة ' + page + ': ' + String((r.err && r.err.message) || '').slice(0, 120);
    if (fails >= MAX_FAILS) { dbg.السبب = 'فشل ' + fails + ' صفحات ورا بعض'; break; }
    await new Promise(res => setTimeout(res, 1500));
    continue;                                   // نتخطى الصفحة دي ونكمل
  }

  const resp = r.data;
  const rows = Array.isArray(resp) ? resp : (resp.results || []);
  if (page === 1) dbg.حجم_الصفحة = rows.length;
  if (!rows.length) { dbg.السبب = 'صفحة ' + page + ' فاضية — خلصت المعاملات'; break; }

  dbg.صفحات = page; dbg.خام += rows.length;

  let oldest = Infinity;
  for (const item of rows) {
    const t = Date.parse(item.paid_at || item.created_at || '');
    if (!isNaN(t)) oldest = Math.min(oldest, t);

    if (item.success !== true) continue;
    if (!isNaN(t) && t < cutoff) continue;
    const tId = String(item.terminal_id || '').trim();
    if (!allowed.includes(tId)) continue;
    if (seen.has(item.id)) continue;
    seen.add(item.id);

    const isRefund  = item.is_refund === true || item.is_refunded === true;
    let amount      = (item.amount_cents || 0) / 100;
    const feesValue = Number(item.fees) || 0;
    const vatValue  = (Number(item.vat_cents_bigint) || 0) / 100;
    let netAmount   = amount - feesValue - vatValue;
    if (isRefund) { amount = -Math.abs(amount); netAmount = -Math.abs(netAmount); }

    const map = terminalMapping[tId];
    out.push({ json: {
      id: item.id, terminal_id: tId, machine_name: map.machine, branch: map.branch,
      order_id: item.order ? String(item.order.id) : null,
      type: isRefund ? 'REFUND' : 'SALE',
      ammount: amount.toFixed(2), fees: feesValue.toFixed(2), vat: vatValue.toFixed(2),
      netammount: netAmount.toFixed(2), balance: null, from: null, to: map.machine,
      closed: null, done: null, is_excess: null,
      createdAt: item.paid_at, updatedAt: null
    }});
  }

  if (oldest !== Infinity) { oldestSeen = oldest; dbg.أقدم_يوم = new Date(oldest).toISOString().slice(0, 10); }
  if (oldest < cutoff) { dbg.السبب = 'وصلنا لـ' + DAYS + ' يوم'; stop = true; break; }

  await new Promise(res => setTimeout(res, 250));
}

dbg.اتحفظ = out.length;
dbg.ثواني = Math.round((Date.now() - started) / 1000);
dbg.السبب = dbg.السبب || ('وقفنا عند صفحة ' + page);

if (!out.length) return [{ json: { _debug: dbg } }];
out.push({ json: { _debug: dbg } });     // امسح السطر ده قبل ما توصّل نود الحفظ
return out;
